# Generates the unrolled ceiling/floor writers pasted into src/render.s
# between the "generated by tools/gen_bgtab.py" markers:
#   python3 tools/gen_bgtab.py > /tmp/bg.s   (then replace the marked block)
# Register contract inside the blocks: A=0xFF B=0xAA C=0x55 D=0x00, HL = pointer.

# ceiling/floor pattern per row y: colour of pixel x (0..7)
def px(y, x):
    if y < 10: return 2                      # ceiling, near: solid dark
    if y < 20: return 2 if y % 2 == 0 else 3 # horizontal lines
    if y < 26: return 2 if y % 4 == 0 else 3 # sparse lines
    if y < 41: return 3                      # horizon band (32 is always wall)
    if y < 47: return 2 if (y % 2 == 0 and (x + y // 2) % 2 == 0) else 3  # 25% dots
    if y < 53: return 2 if (x + y) % 2 == 0 else 3   # 2/3 checker
    if y < 59: return 2                      # solid dark
    return 1 if (x + y) % 2 == 0 else 2      # 1/2 checker, nearest

def row(y):                                  # (lo plane, hi plane)
    lo = hi = 0
    for x in range(8):
        c = px(y, x)
        lo |= (c & 1) << (7 - x); hi |= (c >> 1) << (7 - x)
    return lo, hi

REG = {0xFF: 'a', 0xAA: 'b', 0x55: 'c', 0x00: 'd'}

def store(v, step):                          # step '+' or '-'
    r = REG[v]
    if r == 'a': return ["ld      (hl%s), a" % step]
    return ["ld      (hl), %s" % r, ("inc" if step == '+' else "dec") + "     hl"]

def emit():
    o = []
    o.append("; ceiling entry for maxtop k = code for row k-1 (rows run k-1 .. 0)")
    o.append("ceil_tab:")
    o += ["        .dw     %s" % ("cr%d" % (k - 1) if k else "cr_end") for k in range(33)]
    o.append("; floor entry for minbot k (32..64) = code for row k (rows run k .. 63)")
    o.append("floor_tab:")
    o += ["        .dw     %s" % ("fr%d" % k if k < 64 else "fr_end") for k in range(32, 65)]
    o.append("; ceiling block: HL = hi byte of row maxtop-1, writes backwards")
    o.append("ceil_blk:")
    for y in range(31, -1, -1):
        lo, hi = row(y)
        o.append("cr%d:" % y)
        o += ["        " + s for s in store(hi, '-') + store(lo, '-')]
    o.append("cr_end:")
    o.append("        ret")
    o.append("; floor block: HL = lo byte of row minbot, writes forwards")
    o.append("floor_blk:")
    for y in range(32, 64):
        lo, hi = row(y)
        o.append("fr%d:" % y)
        o += ["        " + s for s in store(lo, '+') + store(hi, '+')]
    o.append("fr_end:")
    o.append("        ret")
    return "\n".join(o)

if __name__ == "__main__":
    print(emit())
